"use strict"

/**
 * @template T
 * @typedef {() => T} FunctionReturning
 */

/**
 * @template T
 * @param {FunctionReturning<T>} fn memorized function
 * @returns {FunctionReturning<T>} new function
 */
/** @type {T | undefined} */ /** @type {T} */
// Allow to clean up memory for fn
// and all dependent resources
/** @type {FunctionReturning<T> | undefined} */ /** @type {T} */

const memoize = (fn) => {
  let cache = false
  let result
  return () => {
    if (cache) {
      return result
    }

    result = fn()
    cache = true
    fn = undefined
    return (result)
  }
}

module.exports = memoize
